import * as T from './three.module.js';
import {setupProfiles} from './profiles.js';
import {polygons,unwrap,contains} from './geography.mjs';
import {createWorld,tick,POLICIES} from './engine.mjs';
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let paintMap=()=>{},geo=[];
let data;try{const response=await fetch('./data.json');if(!response.ok)throw Error('Datos no disponibles');data=await response.json()}catch(e){$('coverage').textContent='No se pudieron cargar los datos. Recarga la página.';throw e}
try{const r=await fetch('./borders.json');if(!r.ok)throw Error();geo=(await r.json()).features}catch{$('worldError').hidden=false;$('worldError').textContent='No se pudo cargar la cartografía. El selector de países sigue disponible.'}
const names=new Intl.DisplayNames(['es'],{type:'region'});data.forEach(d=>{try{d.name=names.of(d.iso2)||d.name}catch{}});data.sort((a,b)=>a.name.localeCompare(b.name,'es'));let world=createWorld(data),baseline=createWorld(data,42,false),selected=data.findIndex(c=>c.id==='ESP'),timer=null,interventions=[];if(selected<0)selected=0;
$('country').innerHTML=data.map((d,i)=>`<option value="${i}">${esc(d.name)}</option>`).join('');$('country').value=selected;$('coverage').textContent=`${data.length} países y economías · ${data.length*24} grupos bot\nDatos de partida: 2024. Parámetros sociales hipotéticos.`;
const method=`<h2>Un laboratorio, no una predicción</h2><p>Versión individual por turnos. No hay personas conectadas, superinteligencia ni modelo de lenguaje. Cada gobierno utiliza un <b>bandido contextual</b>: explora seis políticas, mantiene valores por tres estados (baja confianza, baja producción u otro) y actualiza su estimación con la recompensa observada. No construye argumentos ni creencias lingüísticas.</p><h3>Datos reales y supuestos</h3><p>Países/economías, coordenadas de capital, población y PIB por habitante: <a href="https://data.worldbank.org/indicator/SP.POP.TOTL" target="_blank" rel="noopener">Banco Mundial · población</a> y <a href="https://data.worldbank.org/indicator/NY.GDP.PCAP.CD" target="_blank" rel="noopener">PIB por habitante</a>, año 2024, consulta 08/09/2026, licencia CC BY 4.0. No son datos en tiempo real. Los valores ausentes se muestran como no disponibles.</p><p>El índice productivo inicial es una transformación hipotética del PIB por habitante; los demás parámetros sociales empiezan iguales. Los gobiernos no reproducen instituciones, dirigentes ni ideologías reales. Se incluyen economías de la clasificación del Banco Mundial: no es una declaración de soberanía. Cartografía: Natural Earth, 1:110m, dominio público. Los límites son generalizados, reflejan las convenciones del conjunto de datos y no resuelven disputas territoriales. Los microestados pueden no tener polígono: siguen disponibles como puntos y en el selector. Las capas de confianza y producción muestran índices simulados, no inteligencia real. <a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener">Fuente cartográfica</a>.</p><h3>Reglas explícitas</h3><p>24 grupos bot por economía, con ingresos relativos distintos y bienestar que reacciona a producción, servicios y confianza. No tienen aprendizaje individual en esta versión. No hay todavía nacimientos, migración, empresas ni tratados bilaterales. Comercio depende de la proporción de gobiernos que lo seleccionan.</p><p>Las políticas cuestan unidades de presupuesto; el presupuesto recibe ingresos mensuales. Todos los índices están acotados. Recompensa: cambio de 0,4 × producción + 0,35 × salud + 0,25 × confianza, más un incentivo privado para el desvío ilegal y una penalización si se detecta. El perjuicio social se aplica aunque no se detecte. Son supuestos del modelo, no resultados de investigación.</p><h3>Comparación controlada</h3><p>El escenario adaptativo y el de reglas fijas comparten semilla 42, población, condiciones iniciales y perturbaciones externas. Las diferencias posteriores incluyen efectos de sus decisiones. Una sola ejecución no demuestra superioridad. Exporta la trayectoria, intervenciones y estimaciones para analizarla.</p><p>Fiscalización y crisis se aplican a ambos escenarios. Un turno equivale a un mes; el tiempo se detiene al cerrar esta página. Reiniciar crea un experimento nuevo. No se guarda automáticamente: usa Exportar antes de salir.</p>`;
function show(html){$('dialogContent').innerHTML=html;if(!$('dialog').open)$('dialog').showModal()}$('method').onclick=()=>show(method);$('close').onclick=()=>$('dialog').close();
function render(){const c=world.countries[selected],b=baseline.countries[selected];$('target').textContent=c.id+' / '+c.name.toUpperCase();$('coords').textContent=Math.abs(c.lat).toFixed(2)+'° '+(c.lat>=0?'N':'S')+' / '+Math.abs(c.lon).toFixed(2)+'° '+(c.lon>=0?'E':'O');paintMap();$('date').textContent=`Mes ${world.month}`;$('real').innerHTML=`Población: ${new Intl.NumberFormat('es',{notation:'compact',maximumFractionDigits:1}).format(c.population)} · ${c.year}<br>PIB/hab.: ${c.income?new Intl.NumberFormat('es',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(c.income):'No disponible'} · ${c.year}<br>24 grupos bot · índice productivo inicial aproximado`;
 $('metrics').innerHTML=[['Producción',c.wealth],['Salud',c.health],['Conocimiento',c.knowledge],['Confianza',c.trust]].map(([n,v])=>`<div class="metric"><span>${n}</span><b>${v.toFixed(1)}</b><div class="bar"><i style="width:${v}%"></i></div></div>`).join('');
 $('policy').textContent=c.last?POLICIES[c.policy].name:'A la espera del primer turno';$('reason').textContent=c.last?c.last.reason:'Inicia el experimento para observar decisiones y resultados.';$('learning').innerHTML=c.last?`Valor esperado: ${c.last.expected.toFixed(2)} → recompensa: ${c.last.reward.toFixed(2)}<br>${c.switches} cambios de política · presupuesto: ${c.treasury.toFixed(1)}<br>Reglas fijas: ${POLICIES[b.policy].name}`:'Las estimaciones se actualizan después de actuar.';
 const a=world.history.at(-1)?.wellbeing,base=baseline.history.at(-1)?.wellbeing;$('score').textContent=a==null?'Esperando primer turno':`${a.toFixed(1)} / ${base.toFixed(1)}`;
 const ctx=$('chart').getContext('2d');ctx.clearRect(0,0,500,110);for(const [w,col] of [[world,'#8ae5c7'],[baseline,'#a59be4']]){ctx.strokeStyle=col;ctx.lineWidth=2;ctx.beginPath();w.history.forEach((h,i)=>{const x=i/Math.max(1,w.history.length-1)*490+5,y=105-h.wellbeing; i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()}
 $('events').innerHTML=world.events.filter(e=>e.country===c.id).slice(0,12).map(e=>`<div class="event"><b>Mes ${e.month} · ${esc(e.name)}</b> / ${POLICIES[e.action].name}<small>${esc(e.reason)} · resultado ${e.reward.toFixed(2)} ${e.action!==e.from?'· cambia desde '+POLICIES[e.from].name:''}</small></div>`).join('')||'Sin cambios registrados para este país. Avanza el tiempo.';
}
function advance(n){for(let i=0;i<n;i++){tick(world);tick(baseline)}render()}
function pause(){clearInterval(timer);timer=null;$('play').textContent='▶ Iniciar'}
$('play').onclick=()=>{if(timer)pause();else{timer=setInterval(()=>advance(1),850);$('play').textContent='Ⅱ Pausar'}};$('step').onclick=()=>advance(1);$('year').onclick=()=>advance(12);
$('country').onchange=()=>{selected=+$('country').value;render();focusCountry()};$('enforcement').oninput=e=>{world.enforcement=baseline.enforcement=+e.target.value/100;$('enf').textContent=e.target.value+' %';interventions.push({month:world.month,enforcement:world.enforcement})};$('crisis').onclick=()=>{world.shock=baseline.shock=world.shock?0:1;$('crisis').textContent=world.shock?'Desactivar crisis':'Activar crisis';interventions.push({month:world.month,shock:world.shock})};
$('reset').onclick=()=>{pause();show('<h2>¿Reiniciar el experimento?</h2><p>Se perderá el avance actual. Puedes cerrar este mensaje y exportarlo antes.</p><button id="confirmReset">Reiniciar desde el mes 0</button>');$('confirmReset').onclick=()=>{world=createWorld(data);baseline=createWorld(data,42,false);interventions=[];$('enforcement').value=55;$('enf').textContent='55 %';$('crisis').textContent='Activar crisis';$('dialog').close();render()}};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({version:'0.1.0',dataYear:2024,exportedAt:new Date().toISOString(),interventions,world,baseline},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`civitas-mes-${world.month}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
// Natural Earth boundaries and capital locations; indicators remain simulated.
let renderer,scene,camera,globe,markers=[],azimuth=-.1,elevation=.25,distance=14,drag=null,moved=false;
function point(lat,lon,r=4){const phi=lat*Math.PI/180,theta=lon*Math.PI/180;return new T.Vector3(r*Math.cos(phi)*Math.sin(theta),r*Math.sin(phi),r*Math.cos(phi)*Math.cos(theta))}
function focusCountry(){const c=data[selected];azimuth=c.lon*Math.PI/180;elevation=Math.max(-1.1,Math.min(1.1,c.lat*Math.PI/180))}
try{renderer=new T.WebGLRenderer({canvas:$('globe'),alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));scene=new T.Scene();camera=new T.PerspectiveCamera(42,1,.1,100);globe=new T.Group();scene.add(globe);const sphere=new T.Mesh(new T.SphereGeometry(3.98,64,48),new T.MeshPhongMaterial({color:'#ffffff',shininess:12}));sphere.rotation.y=-Math.PI/2;globe.add(sphere);
 const mapCanvas=document.createElement('canvas');mapCanvas.width=2048;mapCanvas.height=1024;const mc=mapCanvas.getContext('2d'),texture=new T.CanvasTexture(mapCanvas);texture.colorSpace=T.SRGBColorSpace;sphere.material.map=texture;
 const features=geo.map(f=>({f,index:data.findIndex(d=>d.id===f.properties.iso||d.id===f.properties.id)}));
 paintMap=()=>{const mode=$('layer').value;mc.fillStyle='#050f1b';mc.fillRect(0,0,2048,1024);
 for(const {f,index} of features){const c=world.countries[index],chosen=index===selected;
 mc.fillStyle=chosen?'#197f94':mode==='borders'?'#153047':c?`hsl(${Math.round(c[mode]*1.65+8)},45%,${20+c[mode]*.1}%)`:'#182532';mc.strokeStyle=chosen?'#adfaff':'#3c6a82';mc.lineWidth=chosen?2.8:.85;
 for(const poly of polygons(f))for(const offset of [-360,0,360]){mc.beginPath();for(const ring of poly){unwrap(ring).forEach(([lon,lat],i)=>{const x=(lon+180+offset)/360*2048,y=(90-lat)/180*1024;i?mc.lineTo(x,y):mc.moveTo(x,y)});mc.closePath()}mc.fill('evenodd');mc.stroke()}}
 texture.needsUpdate=true;$('layerLegend').textContent=mode==='borders'?'Contornos geográficos · selección en cian':'Índice simulado 0–100 · rojo: bajo / verde: alto · selección en cian';};
 $('layer').onchange=paintMap;paintMap();scene.add(new T.AmbientLight('#a8dacd',1.2));const light=new T.DirectionalLight('#9ef4de',2);light.position.set(-5,5,7);scene.add(light);
 const gridMat=new T.LineBasicMaterial({color:'#387396',transparent:true,opacity:.22});for(let lat=-60;lat<=60;lat+=15){const pts=[];for(let lon=-180;lon<=180;lon+=3)pts.push(point(lat,lon,4));globe.add(new T.Line(new T.BufferGeometry().setFromPoints(pts),gridMat))}for(let lon=-180;lon<180;lon+=20){const pts=[];for(let lat=-90;lat<=90;lat+=3)pts.push(point(lat,lon,4));globe.add(new T.Line(new T.BufferGeometry().setFromPoints(pts),gridMat))}
 data.forEach((d,i)=>{const p=point(d.lat,d.lon,4.06);const m=new T.Mesh(new T.SphereGeometry(.026+Math.min(.065,Math.sqrt(d.population/1e9)*.08),10,8),new T.MeshBasicMaterial({color:'#80dfc2'}));m.position.copy(p);m.userData.index=i;globe.add(m);markers.push(m)});
 const stars=[];for(let i=0;i<450;i++){const a=i*2.399,y=1-2*i/450,r=Math.sqrt(1-y*y);stars.push(35*r*Math.cos(a),35*y,35*r*Math.sin(a))}const sg=new T.BufferGeometry();sg.setAttribute('position',new T.Float32BufferAttribute(stars,3));scene.add(new T.Points(sg,new T.PointsMaterial({color:'#829da8',size:.04,transparent:true,opacity:.45})));
 const selection=new T.Mesh(new T.SphereGeometry(.13,16,12),new T.MeshBasicMaterial({color:'#ffffff',wireframe:true}));globe.add(selection);
 function resize(){const rect=$('globe').parentElement.getBoundingClientRect();renderer.setSize(rect.width,rect.height,false);camera.aspect=rect.width/rect.height;camera.updateProjectionMatrix()}addEventListener('resize',resize);resize();
 const ray=new T.Raycaster();$('globe').onpointerdown=e=>{drag={x:e.clientX,y:e.clientY};moved=false;$('globe').setPointerCapture(e.pointerId)};$('globe').onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>2)moved=true;azimuth-=dx*.007;elevation=Math.max(-1.2,Math.min(1.2,elevation+dy*.005));drag={x:e.clientX,y:e.clientY}};$('globe').onpointerup=e=>{drag=null;if(moved)return;const r=$('globe').getBoundingClientRect();ray.setFromCamera(new T.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);const hits=ray.intersectObjects([...markers,sphere]);let index=hits[0]?.object.userData.index;if(index==null&&hits[0]?.object===sphere){const p=hits[0].point,lat=Math.asin(p.y/p.length())*180/Math.PI,lon=Math.atan2(p.x,p.z)*180/Math.PI;index=features.find(o=>o.index>=0&&contains(o.f,lon,lat))?.index}if(index!=null){selected=index;$('country').value=selected;render()}};$('globe').onpointercancel=()=>drag=null;$('globe').addEventListener('wheel',e=>{e.preventDefault();distance=Math.max(9,Math.min(20,distance+e.deltaY*.008))},{passive:false});$('in').onclick=()=>distance=Math.max(9,distance-1.5);$('out').onclick=()=>distance=Math.min(20,distance+1.5);
 const desired=new T.Vector3();function frame(t){requestAnimationFrame(frame);desired.set(distance*Math.cos(elevation)*Math.sin(azimuth),distance*Math.sin(elevation),distance*Math.cos(elevation)*Math.cos(azimuth));camera.position.lerp(desired,.12);camera.lookAt(0,0,0);selection.position.copy(markers[selected].position);selection.scale.setScalar(1+Math.sin(t*.003)*.2);renderer.render(scene,camera)}camera.position.set(0,4,14);requestAnimationFrame(frame);
}catch(e){$('worldError').hidden=false;$('worldError').textContent='El globo 3D no está disponible. Puedes seguir el experimento con el selector de países.';$('in').disabled=$('out').disabled=true}
render();

setupProfiles({show,getSelected:()=>data[selected].id,onSelect:id=>{const i=data.findIndex(c=>c.id===id);if(i<0)return false;selected=i;$("country").value=i;render();focusCountry();return true}});
